import{_ as e,o as t,c as i,a2 as r}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Blacksmithing","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/professions/blacksmithing.md","filePath":"en/guide/professions/blacksmithing.md"}'),n={name:"en/guide/professions/blacksmithing.md"};function s(o,a,l,d,h,p){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="blacksmithing" tabindex="-1">Blacksmithing <a class="header-anchor" href="#blacksmithing" aria-label="Permalink to &quot;Blacksmithing&quot;">​</a></h1><p><strong>Status:</strong> Proposed · Not established as playable.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Turn metal knowledge and workmanship into dependable equipment.</li><li>Assess, maintain and repair equipment during expeditions.</li><li>Better quality has trade-offs; Masterworks should remain rare.</li></ul><p><span id="at-a-glance"></span><span id="what-it-does"></span><span id="why-take-it-into-the-field"></span><span id="learning-and-specialization"></span><span id="progression-and-related-crafts"></span></p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Activity</th><th>What you do</th></tr></thead><tbody><tr><td>Transform metal</td><td>Smelt, refine, alloy, forge, heat-treat and finish.</td></tr><tr><td>Care for equipment</td><td>Assess materials, sharpen edges and perform minor field repairs.</td></tr><tr><td>Learn</td><td>Keep a Metallurgical Journal; explore Bladesmithing or Armorsmithing techniques.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Compared with classic UO <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Permalink to &quot;Compared with classic UO&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Classic UO</th><th>Syrolands direction</th></tr></thead><tbody><tr><td>Tools, ingots and a crafting menu produce weapons and armor.</td><td>Material preparation, forging and heat treatment shape the result.</td></tr><tr><td>Repair and exceptional quality are already part of the craft.</td><td>Process quality and field assessment deepen maintenance and specialization.</td></tr></tbody></table><p>Comparison uses familiar UO crafting loops; the official references also cover later expansions. <a href="https://uo.com/wiki/ultima-online-wiki/skills/blacksmithing/" target="_blank" rel="noreferrer">Blacksmithing</a>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>A smith could earn a reputation for durable field weapons. Choosing a harder edge may improve one property while increasing brittleness.</p><h2 id="progression-and-trade-offs" tabindex="-1">Progression and trade-offs <a class="header-anchor" href="#progression-and-trade-offs" aria-label="Permalink to &quot;Progression and trade-offs&quot;">​</a></h2><ul><li>Weight, toughness and cutting performance compete; no single material must win every job.</li><li>Arms Lore explains martial performance; Blacksmithing explains materials and structure. Repair limits and material rules remain open.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/professions/mining.html">Mining</a> · <a href="/Syrolands-Public/en/guide/professions/carpentry.html">Carpentry</a> · <a href="/Syrolands-Public/en/guide/items/item-quality.html">Item Quality</a> · <a href="/Syrolands-Public/en/guide/professions/overview.html">Profession System</a></p><h2 id="full-design-specification" tabindex="-1">Full design specification <a class="header-anchor" href="#full-design-specification" aria-label="Permalink to &quot;Full design specification&quot;">​</a></h2><p><a href="/Syrolands-Public/en/game-design/professions/blacksmithing.html">Blacksmithing</a></p>',18)])])}const u=e(n,[["render",s]]);export{m as __pageData,u as default};
